import unittest
from candidate import max_element

class TestMaxElement(unittest.TestCase):
    def test_max_element_normal_case_positive_numbers(self):
        self.assertEqual(max_element([1, 2, 3]), 3)

    def test_max_element_normal_case_mixed_positive_negative(self):
        self.assertEqual(max_element([5, 3, -5, 2, -3, 3, 9, 0, 123, 1, -10]), 123)

    def test_max_element_normal_case_single_element(self):
        self.assertEqual(max_element([42]), 42)

    def test_max_element_normal_case_all_same_elements(self):
        self.assertEqual(max_element([7, 7, 7, 7]), 7)

    def test_max_element_normal_case_floats(self):
        self.assertAlmostEqual(max_element([1.5, 3.2, 2.8]), 3.2)

    def test_max_element_normal_case_negative_numbers(self):
        self.assertEqual(max_element([-10, -5, -3, -1]), -1)

    def test_max_element_boundary_case_two_elements_ascending(self):
        self.assertEqual(max_element([1, 2]), 2)

    def test_max_element_boundary_case_two_elements_descending(self):
        self.assertEqual(max_element([2, 1]), 1)

    def test_max_element_empty_list_raises_index_error(self):
        with self.assertRaises(IndexError):
            max_element([])

    def test_max_element_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            max_element(None)

    def test_max_element_type_error_mixed_incomparable_types(self):
        with self.assertRaises(TypeError):
            max_element([1, 'a'])

    def test_max_element_edge_case_large_numbers(self):
        self.assertEqual(max_element([1000000, 999999, 1000001]), 1000001)

if __name__ == '__main__':
    unittest.main()
